function minWindow(s: string, t: string): string {
  if (t.length > s.length) return '';

  // need[c] — сколько ещё символов c не хватает в окне (может уйти в минус — это избыток)
  const need = new Map<string, number>();
  for (const c of t) need.set(c, (need.get(c) ?? 0) + 1);

  let missing = t.length; // сколько символов t ещё не покрыто окном
  let left = 0;
  let bestStart = 0;
  let bestLen = Infinity;

  for (let right = 0; right < s.length; right++) {
    const c = s[right];
    if (need.has(c)) {
      // Символ был нужен (а не лишний) — покрыли ещё один символ t
      if (need.get(c)! > 0) missing--;
      need.set(c, need.get(c)! - 1);
    }

    // Окно покрывает весь t — сужаем слева, пока покрытие сохраняется
    while (missing === 0) {
      if (right - left + 1 < bestLen) {
        bestLen = right - left + 1;
        bestStart = left;
      }

      const d = s[left];
      if (need.has(d)) {
        need.set(d, need.get(d)! + 1);
        // Убрали символ, без которого окно больше не покрывает t
        if (need.get(d)! > 0) missing++;
      }
      left++;
    }
  }

  return bestLen === Infinity ? '' : s.slice(bestStart, bestStart + bestLen);
}

// Время: O(m + n) — каждый символ s входит в окно и выходит из него по одному разу
// Память: O(k) — частоты различных символов t
